function hash(x,y){let n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function text(s,x,y,size=14,color='#e7dfd1',align='left',font="'Gowun Batang',serif"){ctx.fillStyle=color;ctx.font=`${size}px ${font}`;ctx.textAlign=align;ctx.fillText(s,x,y);ctx.textAlign='left'}
function box(x,y,w,h,fill='#151319',stroke='#54464b'){ctx.fillStyle=fill;ctx.fillRect(x,y,w,h);ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,w-1,h-1)}
function bar(x,y,w,h,v,max,color){ctx.fillStyle='#332b30';ctx.fillRect(x,y,w,h);ctx.fillStyle=color;ctx.fillRect(x,y,w*Math.max(0,v/max),h);ctx.strokeStyle='#8c7565';ctx.strokeRect(x+.5,y+.5,w-1,h-1)}
function visibleCamera(){let vw=740,vh=420;return{x:Math.max(0,Math.min(MW*TILE-vw,player.px+16-vw/2)),y:Math.max(0,Math.min(MH*TILE-vh,player.py+16-vh/2))}}
function drawTile(x,y,type,sx,sy){let h=hash(x,y);if(type===0||type===2){ctx.fillStyle=type===2?(h>.5?'#373330':'#3b3631'):(h>.5?'#222b28':'#252d29');ctx.fillRect(sx,sy,TILE,TILE);ctx.fillStyle=type===2?'#48413a':'#303a32';ctx.fillRect(sx+((x*13+y*7)%27),sy+((y*11+x*3)%25),2,2);if(h>.86){ctx.fillStyle='#777052';ctx.fillRect(sx+10,sy+22,3,2)}}else if(type===1){ctx.fillStyle='#17211e';ctx.fillRect(sx,sy,TILE,TILE);ctx.fillStyle='#49372f';ctx.fillRect(sx+13,sy+17,7,15);ctx.fillStyle='#263a31';ctx.fillRect(sx+4,sy+5,24,17);ctx.fillStyle='#314638';ctx.fillRect(sx+8,sy+2,16,13);ctx.fillStyle='#40513b';ctx.fillRect(sx+12,sy+4,6,6);ctx.fillStyle='#18221e';ctx.fillRect(sx+7,sy+19,19,3)}else if(type===3){ctx.fillStyle='#282827';ctx.fillRect(sx,sy,TILE,TILE);ctx.fillStyle='#67635a';ctx.fillRect(sx+12,sy+8,9,20);ctx.fillStyle='#827b6b';ctx.fillRect(sx+10,sy+7,13,5);ctx.fillStyle='#312e2d';ctx.fillRect(sx+14,sy+14,3,11)}else{ctx.fillStyle='#191e22';ctx.fillRect(sx,sy,TILE,TILE);ctx.fillStyle='#343a3b';ctx.fillRect(sx+2,sy+9,28,13);ctx.fillStyle='#51504a';ctx.fillRect(sx+8,sy+12,3,3)}}
function drawPerson(px,py,kind='player',phase=0){let x=Math.round(px),y=Math.round(py);ctx.fillStyle='#08090ab0';ctx.beginPath();ctx.ellipse(x+16,y+27,10,4,0,0,Math.PI*2);ctx.fill();if(kind==='player'){ctx.fillStyle='#282126';ctx.fillRect(x+8,y+12,16,14);ctx.fillStyle='#583b38';ctx.fillRect(x+7,y+11,18,8);ctx.fillStyle='#b49b7c';ctx.fillRect(x+11,y+3,10,11);ctx.fillStyle='#291e24';ctx.fillRect(x+9,y+2,14,5);ctx.fillStyle='#d2b579';ctx.fillRect(x+13,y+8,2,2);ctx.fillStyle='#6b433d';ctx.fillRect(x+6,y+14,5,10);ctx.fillStyle='#18161b';ctx.fillRect(x+10,y+25,5,4);ctx.fillRect(x+18,y+25,5,4);if(phase%2){ctx.fillStyle='#c2a883';ctx.fillRect(x+14,y+16,3,5)}}else if(kind==='npc'){ctx.fillStyle='#3e3439';ctx.fillRect(x+7,y+10,18,17);ctx.fillStyle='#a7937e';ctx.fillRect(x+11,y+4,10,9);ctx.fillStyle='#564342';ctx.fillRect(x+10,y+3,12,4);ctx.fillStyle='#d3b172';ctx.fillRect(x+14,y+8,3,2)} }
function drawLandmark(d,sx,sy){let x=sx+d.x*TILE,y=sy+d.y*TILE;if(d.type==='fire'){let flick=Math.sin(worldTime*8)*2;ctx.fillStyle='#25201c';ctx.fillRect(x+5,y+22,22,6);ctx.fillStyle='#a05237';ctx.fillRect(x+11,y+11+flick,10,13-flick);ctx.fillStyle='#e3b46d';ctx.fillRect(x+14,y+13+flick,5,9);ctx.fillStyle='#ffe2a0';ctx.fillRect(x+15,y+16+flick,2,5);ctx.fillStyle='#bd6545';ctx.beginPath();ctx.arc(x+16,y+16,21+Math.sin(worldTime*3)*3,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.12;ctx.fillStyle='#f0a568';ctx.beginPath();ctx.arc(x+16,y+16,45,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}else if(d.type==='shrine'){ctx.fillStyle='#51473e';ctx.fillRect(x+4,y+11,24,18);ctx.fillStyle='#82705a';ctx.fillRect(x+2,y+7,28,6);ctx.fillStyle='#b88a68';ctx.fillRect(x+11,y+3,10,22);ctx.fillStyle='#332c2c';ctx.fillRect(x+14,y+10,4,9);ctx.fillStyle='#e0c591';ctx.fillRect(x+15,y+12,2,4)}else if(d.type==='npc'){drawPerson(x,y,'npc');ctx.fillStyle='#d9bb84';ctx.fillRect(x+12,y-2,8,7);text('!',x+16,y-7,12,'#e1c98b','center')}else if(d.type==='gate'){ctx.strokeStyle='#887269';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x+5,y+30);ctx.lineTo(x+5,y+12);ctx.quadraticCurveTo(x+16,y-2,x+27,y+12);ctx.lineTo(x+27,y+30);ctx.stroke();ctx.strokeStyle='#b99a72';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x+16,y+8);ctx.lineTo(x+16,y+27);ctx.stroke();ctx.fillStyle='#d0b782';ctx.fillRect(x+14,y+14,4,4)}else{ctx.fillStyle='#a1a094';ctx.fillRect(x+12,y+7,8,22);ctx.fillStyle='#cbc5ae';ctx.fillRect(x+10,y+6,12,5);ctx.fillStyle='#504b48';ctx.fillRect(x+14,y+14,3,11)}}
function drawWorld(){let c=visibleCamera(),vw=740,vh=420;ctx.save();ctx.beginPath();ctx.rect(0,45,vw,vh);ctx.clip();ctx.fillStyle='#202724';ctx.fillRect(0,45,vw,vh);let x0=Math.floor(c.x/TILE),y0=Math.floor(c.y/TILE);for(let y=y0;y<Math.min(MH,y0+16);y++)for(let x=x0;x<Math.min(MW,x0+25);x++)drawTile(x,y,map[y][x],Math.floor(x*TILE-c.x),45+Math.floor(y*TILE-c.y));for(const d of decor)drawLandmark(d,-c.x,45-c.y);drawPerson(player.px-c.x,45+player.py-c.y,'player',Math.floor(elapsed*8));
// drifting fireflies and fog
for(let i=0;i<18;i++){let fx=(hash(i,2)*740+Math.sin(elapsed*.3+i)*16),fy=65+hash(i,7)*370+Math.cos(elapsed*.2+i)*8;ctx.globalAlpha=.12+.14*(1+Math.sin(elapsed*2+i));ctx.fillStyle=i%4?'#d8c28c':'#a6bba1';ctx.fillRect(fx,fy,2,2)}ctx.globalAlpha=1;let grad=ctx.createRadialGradient(370,260,90,370,260,510);grad.addColorStop(0,'#090a0d00');grad.addColorStop(1,'#08090bbf');ctx.fillStyle=grad;ctx.fillRect(0,45,vw,vh);ctx.restore();}
function drawHud(){box(748,48,198,455,'#151319eF','#57474a');text('잿빛 숲',765,76,19,'#e1d4c0');text('灰の森 · DUSK',765,96,10,'#9b8c7c','left',"'IBM Plex Mono',monospace");ctx.strokeStyle='#51444a';ctx.beginPath();ctx.moveTo(764,108);ctx.lineTo(930,108);ctx.stroke();text('여행자',765,132,12,'#c7b9a6');text('Lv.'+player.level,929,132,11,'#d7c6a9','right',"'IBM Plex Mono',monospace");bar(765,142,164,9,player.hp,player.max,'#a85e56');text(`HP ${player.hp} / ${player.max}`,765,169,11,'#d4c8b8','left',"'IBM Plex Mono',monospace');text('동행',765,204,13,'#d7c6a9');party.slice(0,3).forEach((m,i)=>{let y=222+i*65,info=monsters[m.kind];box(762,y,171,56,'#1c191d','#40373b');text(info.icon,778,y+23,17,info.color);text(info.name,802,y+20,12,'#e4d8c8');text(`Lv.${m.level}`,920,y+20,10,'#b8a58d','right',"'IBM Plex Mono',monospace");bar(802,y+30,116,6,m.hp,m.max,'#71866b');text(`${m.hp}/${m.max}`,920,y+48,9,'#938a7e','right',"'IBM Plex Mono',monospace")});ctx.strokeStyle='#51444a';ctx.beginPath();ctx.moveTo(764,423);ctx.lineTo(930,423);ctx.stroke();text('가방',765,447,12,'#d7c6a9');text(`봉인구슬  × ${inventory.seal}`,765,469,11,'#beb2a3');text(`약초       × ${inventory.potion}`,765,490,11,'#beb2a3');text('Z 확인   X 기록',765,523,10,'#897d72','left',"'IBM Plex Mono',monospace');
box(15,472,710,105,'#111015e8','#5f4e4e');ctx.fillStyle='#bc8b72';ctx.fillRect(28,487,2,68);text('기록',42,499,10,'#bd9b7c');for(let i=0;i<3;i++){let line=log[i]||'';text(line,42,520+i*18,13,i===0?'#e4d8c8':'#a89c8c')}
// contextual prompt
let near=getNearby();if(near){ctx.fillStyle='#1b1719e8';ctx.fillRect(278,431,188,28);ctx.strokeStyle='#8b765f';ctx.strokeRect(278.5,431.5,187,27);text('Z  '+near.label,372,450,11,'#e4d8c8','center')}
}

