function getNearby(){if(!player)return null;for(const d of decor){let dist=Math.abs(d.x-player.x)+Math.abs(d.y-player.y);if(dist<=1.5){return{...d,label:({fire:'화톳불에서 쉰다',shrine:'낡은 비석을 살핀다',npc:'수상한 사내와 대화한다',gate:'검은 문을 살핀다',grave:'묘비를 읽는다'})[d.type]}}}return null}
function addLog(s){log.unshift(s);log=log.slice(0,3)}
function toast(s){toastEl.textContent=s;toastEl.style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastEl.style.opacity=0,1900)}
function startGame(){blankGame();state='play';title.classList.add('hidden');playMusic();}
function interact(){if(state==='title'){startGame();return}if(state==='combat'){combatAction();return}if(state==='menu'){menuAction();return}let d=getNearby();if(!d){toast('아무 일도 일어나지 않았다.');return}if(d.type==='fire'){party.forEach(m=>m.hp=m.max);player.hp=player.max;inventory.potion=Math.min(5,inventory.potion+1);addLog('화톳불에서 숨을 고르고 약초를 얻었다.');saveGame();toast('불빛 아래에서 상처가 아물었다.');return}if(d.type==='shrine'){if(!flags.shrine){flags.shrine=true;player.max+=6;player.hp=player.max;addLog('비석이 당신의 이름을 기억했다. 최대 HP +6');toast('오래된 이름이 당신을 축복한다.')}else{player.hp=player.max;party.forEach(m=>m.hp=m.max);toast('비석의 온기가 상처를 덮었다.')}return}if(d.type==='npc'){addLog('가면 쓴 순례자: “구슬은 약해진 숨결에 던져. 그리고…');addLog('가면 쓴 순례자: “숲의 짐승도 한때는 누군가의 가족이었지.”');inventory.seal++;toast('봉인구슬을 하나 받았다.');return}if(d.type==='grave'){addLog('묘비에는 이름 대신 “집으로”라고 새겨져 있다.');toast('차가운 돌 아래서 작은 빛이 깜빡인다.');return}if(d.type==='gate'){if(!flags.stag){addLog('검은 문 너머에서 뿔이 돌을 긁는 소리가 난다.');toast('문은 깊은 잠에 빠져 있다.');return}if(!flags.gate){flags.gate=true;addLog('검은 문이 열리고, 먼 달빛이 길을 비춘다.');toast('새로운 여정의 첫 장이 열렸다.');}else toast('달빛 아래 길이 이어진다.');return}}
function move(dx,dy){if(state!=='play')return;let nx=player.x+dx,ny=player.y+dy;if(nx<1||ny<1||nx>=MW-1||ny>=MH-1||map[ny][nx]===1||map[ny][nx]===3||map[ny][nx]===4)return;player.dir=dx<0?'left':dx>0?'right':dy<0?'up':'down';player.x=nx;player.y=ny;player.px=nx*TILE;player.py=ny*TILE;player.steps++;if(player.steps%7===0&&Math.random()<.54&&map[ny][nx]!==2)beginBattle();else if(player.steps%9===0&&Math.random()<.22)beginBattle();}
function beginBattle(kind){if(state!=='play')return;let choices=kind?[kind]:['moth','hound','root','wisp'];let mob=choices[Math.floor(Math.random()*choices.length)];if(mob==='stag'&&flags.stag)return;let base=monsters[mob];combat={kind:mob,hp:base.max+Math.floor(Math.random()*5),max:base.max+4,turn:0,sel:0,message:'어둠 속에서 '+base.name+'이 모습을 드러냈다.',phase:'command'};state='combat';beep(90,.2,.04,'triangle');}
function combatAction(index){if(!combat)return;let n=typeof index==='number'?index:combat.sel;let m=party[0],info=monsters[combat.kind];if(combat.phase==='result'){finishBattle();return}if(n===0){let dmg=4+m.level*2+Math.floor(Math.random()*4);combat.hp=Math.max(0,combat.hp-dmg);combat.message=`${info.name}에게 ${dmg}의 피해를 주었다.`;beep(170,.08,.04,'square')}else if(n===1){let dmg=7+m.level*2;combat.hp=Math.max(0,combat.hp-dmg);m.hp=Math.min(m.max,m.hp+3);combat.message=`${monsters[m.kind].skill}! ${dmg} 피해, 동행이 숨을 고른다.`;beep(260,.16,.04,'sine')}else if(n===2){if(inventory.seal<=0){combat.message='봉인구슬이 없다. 순례자에게 구할 수 있다.';return}inventory.seal--;let chance=.24+(1-combat.hp/combat.max)*.63+(combat.kind==='wisp'?.08:0);if(Math.random()<chance){party.push({kind:combat.kind,hp:Math.ceil(combat.max*.62),max:info.max,level:1});combat.message=`${info.name}이 봉인구슬 안에서 숨을 고른다. 동행이 되었다.`;addLog(info.name+'을(를) 동료로 맞이했다.');combat.phase='result';return}else{combat.message=`구슬이 흔들리다 깨졌다. (${Math.round(chance*100)}% 포획 확률)`;beep(100,.22,.05,'sawtooth')}}else{if(inventory.potion<=0){combat.message='약초가 없다.';return}inventory.potion--;player.hp=Math.min(player.max,player.hp+16);m.hp=Math.min(m.max,m.hp+12);combat.message='붉은 약초를 나눠 먹었다. HP가 회복되었다.';beep(500,.12,.03,'sine')}
if(combat.hp<=0){combat.message=info.name+'은 조용히 숲으로 돌아갔다.';combat.phase='result';player.xp+=12;return}combat.turn++;let enemyDmg=Math.max(2,info.atk+Math.floor(Math.random()*4)-m.level);player.hp=Math.max(0,player.hp-enemyDmg);combat.message+=` ${info.name}의 반격! ${enemyDmg} 피해.`;shake=7;if(player.hp<=0){combat.message='의식이 흐려진다… 화톳불에서 눈을 떴다.';combat.phase='result';combat.defeat=true}}
function finishBattle(){if(combat.defeat){player.hp=Math.ceil(player.max*.6);player.x=8;player.y=20;player.px=player.x*TILE;player.py=player.y*TILE;party.forEach(m=>m.hp=Math.max(1,Math.ceil(m.max*.5)));addLog('화톳불에서 깨어났다. 잃은 것은 없지만 숲은 기억한다.')}if(combat.kind==='stag'&&!combat.defeat){flags.stag=true;addLog('검은 사슴이 머리를 숙인다. 검은 문이 열릴 것이다.');}if(player.xp>=20){player.xp-=20;player.level++;player.max+=5;player.hp=player.max;party[0].level++;party[0].max+=4;party[0].hp=party[0].max;addLog('레벨이 올랐다. 숲이 당신을 두려워하기 시작한다.')}addLog('전투가 끝났다.');combat=null;state='play';saveGame()}

