28: function L(s){if(lang==='ko'||typeof s!=='string')return s;if(en[s])return en[s];const mob=n=>replacements[n]||n;if(/에게 \d+의 피해를 주었다\.$/.test(s)){let m=s.match(/^(.+?)에게 (\d+)의 피해를 주었다\.$/);return `${mob(m[1])} took ${m[2]} damage.`}if(/에게 \d+ 피해, 동행이 숨을 고른다\.$/.test(s)){let m=s.match(/^(.+?)에게 (\d+) 피해, 동행이 숨을 고른다\.$/);return `${mob(m[1])}: ${m[2]} damage; your companion catches its breath.`}if(/의 반격! \d+ 피해\.$/.test(s)){let m=s.match(/^(.+?)의 반격! (\d+) 피해\.$/);return `${mob(m[1])} strikes back for ${m[2]} damage.`}if(/이 모습을 드러냈다\.$/.test(s)){let n=s.replace(/이 모습을 드러냈다\.$/,'');return `${mob(n)} appears from the darkness.`}if(/이 봉인구슬 안에서 숨을 고른다\. 동행이 되었다\.$/.test(s)){let n=s.replace(/이 봉인구슬 안에서 숨을 고른다\. 동행이 되었다\.$/,'');return `${mob(n)} settles inside the Sealing Orb and joins you.`}if(/을\(를\) 동료로 맞이했다\.$/.test(s)){let n=s.replace(/을\(를\) 동료로 맞이했다\.$/,'');return `${mob(n)} joined your party.`}if(/구슬이 흔들리다 깨졌다\./.test(s))return s.replace(/구슬이 흔들리다 깨졌다\./,'The orb trembles and shatters.').replace(/포획 확률/,'capture chance');if(s.endsWith('!'))return s.replace(/!$/,'!');let out=s;for(const [a,b] of Object.entries(replacements))out=out.replaceAll(a,b);for(const [a,b] of Object.entries(en))if(a.length>4&&out.includes(a))out=out.replaceAll(a,b);return out}
